/**
 * @method
 * @name cmb_TeamList_onselchange
 * @description cmb_TeamList onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_TeamList_onselchange = function() {
    try {
        scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
        if (scwin.gDepCd === '') {
            cmb_TeamList.setValue('');
        }
        dts_emp.UseFilter = true;
        dts_emp.Filter();
        dts_emp.sort("DEP_CD", 0);
        // dts_emp.sort(); // W-Craft 주석처리
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF22000.cmb_TeamList_onselchange" });
    }
};

/**
 * @method
 * @name dts_emp_OnFilter
 * @description emp On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnFilter = function(row) {
    try {
        //  부서코드에  해당하는 사원을 가져온다.
        if (scwin.gDepCd === "") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_emp.getCellData(row, "dep_cd") === scwin.gDepCd || dts_emp.getCellData(row, "dep_cd") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF22000.dts_emp_OnFilter" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_OnDblClick = function(row, colid) {
    try {
        // 클릭된 값 변수에 셋팅
        scwin.setContnId(row);
        if (colid === "COM_ABBRV") {
            $c.stf.fn_PopupCorpInfo();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF22000.grd_List_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF22000.xml", SCREN_PROCS_TP_CD_07); // 엑셀
        $c.data.downloadGridViewExcel(grd_List, {fileName: "상장원부현황", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF22000.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else return true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF22000.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onkeyup
 * @description txb_ISUR_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onkeyup = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF22000.txb_ISUR_CD_onkeyup" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onfocus
 * @description txb_ISUR_CD 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF22000.txb_ISUR_CD_onfocus" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF22000.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
