};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    scwin.gDepCd = js_dep_cd;
    chb_Grp_All.setValue(1);
    scwin.allCheck();

    /*
            //  기간 from~ to  셋팅
    		var vCurDate = cGetToday("yyyymmdd");
    		edt_SDate.text = '19000101';    // 백윤경대리 요청(2008.10.07)
            //edt_SDate.text = cGetMinusDate2(vCurDate, 3650);  // 1년전 날짜
    		edt_SDate.text = cGetToday("yyyymmdd");     // 현재날짜
    		edt_EDate.text = cGetToday("yyyymmdd");     // 현재날짜
     */
    const ToDay = new Date();
    const yyyy = parseInt(ToDay.getYear(), 10);
    let str = "";
    for (let i = yyyy; i >= 2004; i--) {
        str += i + "^" + i + "년,";
    }
    str = str.substring(0, str.length - 1);
    // alert(str);
    cmb_STD_YEAR.CBData = str;

    // Combo_CBDataSetPeriod(cmb_PeriodTp);

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    // dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    const sbmOptions = {
        id : "sbm_dts_dep",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_dep=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)
    const sbmOptions2 = {
        id : "sbm_dts_emp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_emp=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    /*
    		dts_Indp.DataID="/ListedSearch.do?method=listMiddleIndustry&outputMessageId=LIST_MIDDLE_INDUSTRY" ;
    		dts_Indp.Reset();
     */

};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    let secuGrpId = "";
    if (chb_Grp_St.getValue() === 'Y') secuGrpId += 'ST,';
    // if (getObjectValue(chb_Grp_Mf) == 'Y')        secuGrpId += 'MF,';
    if (chb_Grp_Rt.getValue() === 'Y') secuGrpId += 'RT,';
    if (chb_Grp_Sc.getValue() === 'Y') secuGrpId += 'SC,';
    if (chb_Grp_Fs.getValue() === 'Y') secuGrpId += 'FS,';
    if (chb_Grp_Dr.getValue() === 'Y') secuGrpId += 'DR,';
    // if (getObjectValue(chb_Grp_If) == 'Y')    secuGrpId += 'IF,';
    if (chb_Grp_All.getValue() === ' Y') secuGrpId = '';
    url += "?SCREN_ID=" + "ULDSTF22000.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=LIST_EMP_CNT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.empcnt" + "&{P}param01=" + rdo_LIST_STAT_CD.getValue() + // 상장구분
        "&{P}param02=" + rdo_LIST_STAT_CD.getValue() + // 상장구분
        "&{P}param03=" + txb_ISUR_CD.getValue() + // 법인코드회사코드
        "&{P}param04=" + txb_ISUR_CD.getValue() + // 법인코드회사코드
        "&{P}param05=" + cmb_TeamList.getValue() + // 담당팀
        "&{P}param06=" + cmb_TeamList.getValue() + // 담당팀
        "&{P}param07=" + cmb_EmpList.getValue() + // 담당자
        "&{P}param08=" + cmb_EmpList.getValue() + // 담당자
        "&{P}param09=" + rdo_MARKET_TP_CD.getValue() + // 시장구분
        "&{P}param10=" + rdo_MARKET_TP_CD.getValue() + // 시장구분
        "&{P}param11=" + secuGrpId + // 회사구분
        "&{P}param12=" + secuGrpId + // 회사구분
        "&{P}param13=" + cmb_STD_YEAR.getValue() + // 시작일자
        "&{P}param14=" + cmb_STD_YEAR.getValue(); // 시작일자

    /*

    		 "&{P}param13=" + getObjectValue(edt_SDate) + // 시작일자
    		 "&{P}param14=" + getObjectValue(edt_SDate); // 시작일자

    		var url = "/listingCommon.do?method=listGeneral" +
    			"&outputMessageId=LIST_CORPORATIONBOOK_ISUINST" +
    			"&service=krx.lds.stf.listingcommon.services.ListingCommonApp" +
    			"&queryId=lds.stf.lstsrch.select.isuinst.condition"+
    			"&{P}param01=" + getObjectValue(rdo_MARKET_TP_CD) + // 시장구분
    			"&{P}param02=" + getObjectValue(rdo_MARKET_TP_CD) + // 시장구분
    			"&{P}param03=" + secuGrpId + // 회사구분
    			"&{P}param04=" + secuGrpId + // 회사구분
    			"&{P}param05=" + getObjectValue(rdo_LIST_STAT_CD) + // 상장구분
    			"&{P}param06=" + getObjectValue(rdo_LIST_STAT_CD) + // 상장구분
    			"&{P}param07=" + getObjectValue(txb_ISUR_CD) + // 법인코드
    			"&{P}param08=" + getObjectValue(txb_ISUR_CD) + // 법인코드
    			"&{P}param09=" + getObjectValue(rdo_LIST_DATE_COND) +// 기간 조건
    			"&{P}param10=" + getObjectValue(edt_SDate) +// 시작일자
    			"&{P}param11=" + getObjectValue(edt_EDate) +// 종료일자
    			"&{P}param12=" + getObjectValue(rdo_LIST_DATE_COND) +// 기간 조건
    			"&{P}param13=" + getObjectValue(edt_SDate) +// 시작일자
    			"&{P}param14=" + getObjectValue(edt_EDate) +// 종료일자
    			"&{P}param15=" + getObjectValue(cmb_TeamList) +// 팀
    			"&{P}param16=" + getObjectValue(cmb_TeamList) +// 팀
