///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name allCheck
 * @description all Check 처리
 * @returns {void}
 * @hidden N
 */
scwin.allCheck = function() {
    const checkArray = [chb_Grp_St, chb_Grp_Sc, chb_Grp_Rt, chb_Grp_Dr, chb_Grp_Fs];
    if (chb_Grp_All.checked === true) {
        for (let i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(0);
        }
    }
};

/**
 * @method
 * @name setContnId
 * @description set Contn Id 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gIsurCd = dts_List.getCellData(Number(obj), "ISUR_CD");
};
